	if err != nil {
		return err
	}
	var results []workspaceQueryResult
	for _, repo := range manifest.Repos {
		result := workspaceQueryResult{RepoKey: repo.RepoKey, Name: repo.Name}
		brainDir, err := brainDirForKey(opts.Env, repo.RepoKey)
		if err != nil {
			return err
		}
