		if err != nil {
			result.Error = err.Error()
			results = append(results, result)
			continue
		}
		symbols, _, err := semanticContextFacts(brainDir, source, query, queryOpts.limit, 0)
		if err != nil {
			result.Error = err.Error()
		} else {
			result.Symbols = symbols
		}
		results = append(results, result)
	}
	if queryOpts.json {
		return writeJSON(cmd, struct {
