			if os.IsNotExist(err) {
				status.State = "missing-brain"
				result = append(result, status)
				continue
			}
			status.State = "unsafe"
			status.Detail = err.Error()
			result = append(result, status)
			continue
		}
		brainManifest, err := loadBrainManifest(brainDir)
		switch {
		case os.IsNotExist(err):
			status.State = "missing-brain"
		case err != nil:
			status.State = "unsafe"
			status.Detail = err.Error()
		case brainManifest.Sources == nil || brainManifest.Sources.Semantic == nil:
			status.State = "missing-semantic"
		default:
			status.State = "ok"
			status.Detail = brainManifest.Sources.Semantic.SnapshotPath
		}
		result = append(result, status)
	}
	return result, nil
}

